	srcContent, err := ioutil.ReadFile(srcFile)
	if err != nil {
		log.Fatal(err)
	}

	// Parse the Go source file for the struct definition
	structDef, err := extractStructDefinition(string(srcContent), structName)
	if err != nil {
		log.Fatal(err)
	}

	// Generate the Avro schema
	schema, err := genAvroSchema(structDef)
	if err != nil {
		log.Fatal(err)
	}

	// Write the Avro schema to a file
	err = ioutil.WriteFile(outputFile, []byte(schema), 0644)
	if err != nil {
		log.Fatal(err)
	}

	fmt.Printf("Avro schema generated successfully: %s\n", outputFile)
}

func extractStructDefinition(src string, structName string) (*reflect.Struct, error) {
	// Split the Go source file into lines
	lines := strings.Split(src, "\n")

	// Find the line that contains the struct definition
