```python
import nltk
from nltk.corpus import stopwords
from nltk.tokenize import word_tokenize
from collections import Counter

def get_vowels():
    return set('aeiou')

def get_consonants(text):
    vowels = get_vowels()
    consonants = ''.join(c for c in text if c not in vowels)
    return consonants

def count_combinations(text):
    consonants = get_consonants(text)
    vowels = get_vowels()

    # Create a dictionary to store the counts of each combination
    combos = {}

    # Loop through all possible combinations of vowels and consonants
    for i in range(len(consonants)):
        for j in range(len(vowels)):
            combo = f"{consonants[i]}{vowels[j]}"
            if combo in combos:
                combos[combo] += 1
            else:
                combos[combo] = 1

    return combos

def main():
    text = "This is a sample text to analyze."
    combinations = count_combinations(text)

    # Print the most frequent combinations
    print("Most frequent combinations:")
    for combo, count in combinations.most_common():
        print(f"{combo}: {count}")

if __name__ == "__main__":
    main()
```

This script will output the most frequent combinations of non-silent vowels and consonants in the given text. You can modify the `text` variable to analyze different texts.

