Here's a simple React utility that removes widows by adjusting the font size of an element if it exceeds the maximum width:

```javascript
import React, { useRef } from 'react';

const RemoveWidows = ({ children }) => {
  const textRef = useRef(null);

  const handleResize = () => {
    const textWidth = textRef.current.offsetWidth;
    const maxWidth = 800; // Adjust this value based on your desired maximum width

    if (textWidth > maxWidth) {
      const newFontSize = Math.floor(maxWidth / textWidth) * 100;
      textRef.current.style.fontSize = `${newFontSize}%`;
    }
  };

  return (
    <div ref={textRef} onResize={handleResize}>
      {children}
    </div>
  );
};

export default RemoveWidows;
```

