#include <iostream>
#include <curl/curl.h>

using namespace std;

string getFacebookData(string url) {
    CURL *curl;
    CURLcode res;
    string readBuffer;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    return readBuffer;
}

int main() {
    string facebookUrl = "https://graph.facebook.com/v12.0/your_page_id/posts"; // Replace with your actual Facebook page ID
    string data = getFacebookData(facebookUrl);

    // Process the retrieved data
    cout << "Retrieved data from Facebook:" << endl << data << endl;

    return 0;
}
```

Replace `"your_page_id"` with your actual Facebook page ID. This code will fetch the posts from the specified page and print them to the console. You can further process the data as needed.

Please note that this code does not use any external libraries. It relies on the built-in CURL library for making HTTP requests.

