import java.util.HashMap;
import java.util.Map;

public class AIAssistant {
    private Map<String, String> responses = new HashMap<>();

    public void learn(String query, String response) {
        responses.put(query, response);
    }

    public String respond(String query) {
        if (responses.containsKey(query)) {
            return responses.get(query);
        } else {
            // Add additional logic here to handle the problematic phrase
            if (query.contains("problematic phrase")) {
                return "I'm sorry, I don't understand that. Can you please rephrase your question?";
            } else {
                return "I'm not sure how to help with that. Can you provide more context?";
            }
        }
    }
}
```
